import{_ as a,c as t,o as i,ag as n}from"./chunks/framework.DPDPlp3K.js";const c=JSON.parse('{"title":"Installing & Updating","description":"","frontmatter":{"title":"Installing & Updating"},"headers":[],"relativePath":"install-update.md","filePath":"install-update.md"}'),l={name:"install-update.md"};function o(s,e,d,r,p,h){return i(),t("div",null,e[0]||(e[0]=[n('<h2 id="how-to-install" tabindex="-1">How to install <a class="header-anchor" href="#how-to-install" aria-label="Permalink to &quot;How to install&quot;">​</a></h2><p>To install the plugin from CodeCanyon, simply upload the plugin ZIP file to your site via <code>Plugins</code> ▹ <code>Add New</code> ▹ <code>Upload Plugin</code>.</p><p>Alternatively, unzip the plugin ZIP file and upload the resulting folder to your site&#39;s <code>/wp-content/plugins/</code> directory. Don&#39;t forget to activate it through the <code>Plugins</code> menu in your WordPress dashboard.</p><h2 id="upgrading-from-the-lite-version" tabindex="-1">Upgrading from the Lite version <a class="header-anchor" href="#upgrading-from-the-lite-version" aria-label="Permalink to &quot;Upgrading from the Lite version&quot;">​</a></h2><p>The lite version and full version plugins operate independently. In other words, only one of them can and should be installed at the same time.</p><p>If you have the lite version installed, installing the full version will deactivate it. You can safely uninstall the lite version before or after installing the full version. Your attribute stock data will not be deleted (see <a href="#deleting-database-data">Deleting database data</a> below).</p><h2 id="how-to-update" tabindex="-1">How to update <a class="header-anchor" href="#how-to-update" aria-label="Permalink to &quot;How to update&quot;">​</a></h2><p>Automatic updates can be enabled in WordPress by authorizing your Envato account.</p><p>If you&#39;re using the plugin on multiple sites, you&#39;ll need to use the <a href="https://envato.com/market-plugin/" target="_blank" rel="noreferrer">Envato Market WordPress Plugin</a> instead. Make sure you have the correct licenses, i.e. one regular license per company, or an extended license for unlimited usage.</p><p>If updating manually, the procedure is the same as <a href="#installing">installing</a> the plugin ZIP file.</p><h2 id="deleting-database-data" tabindex="-1">Deleting database data <a class="header-anchor" href="#deleting-database-data" aria-label="Permalink to &quot;Deleting database data&quot;">​</a></h2><p>By default, when you uninstall WooCommerce Attribute Stock, all of the attribute stock data you&#39;ve added will remain in your database. This safeguards against accidental data loss.</p><p>If you want all attribute stock data to be deleted when uninstalling, simply add the below line to your <code>wp-config.php</code> file before uninstalling the plugin:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">define</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MEWZ_DELETE_DATA&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div>',14)]))}const g=a(l,[["render",o]]);export{c as __pageData,g as default};
